  time: number;
  durationMark: string;
  octave: number;
  accidental: string;
  annotation: string | null;
  detachedAnnotation?: boolean;
  isHiddenRest: boolean;
  measureIndex: number;
  notepos: string;
  lineIndex: number;
  groupSize?: number;
  groupStart?: boolean;
  groupEnd?: boolean;
  slurStartCount?: number;
  slurEndCount?: number;
  hairpinStart?: "crescendo" | "diminuendo";
  hairpinEnd?: boolean;
  hairpinDefaultOffset?: boolean;
  dynamicMark?: string;
  accompanimentBracket?: "left" | "right";
  articulations?: Array<"dy" | "zy" | "bc" | "hx">;
