  const glyphDiscoveryChildren = [...svgChildren, ...durationLineChildren, ...naturalPitchDecorationChildren, ...octaveGlyphChildren, ...groupedDecorationChildren, ...markingChildren, ...expressionChildren, ...jumpHouseChildren];
